import numpy as np
x=df['x'].values; v=df['v'].values; a=df['dv_dt'].values; t=df['t'].values
w=0.31305
names=[];cols=[]
for i in range(5):
    for j in range(5-i):
        names.append(f'x^{i} v^{j}'); cols.append(x**i*v**j)
names+=['cos','sin']; cols+=[np.cos(w*t),np.sin(w*t)]
